SELECT * FROM ( ( SELECT a.warn_id, a.device_id, b.device_name, k.mete_name, b.custom_name, a.warn_content, a.warn_level AS alarm_level, c.dict_note AS alarm_level_name, a.alarm_source, d.dict_note AS alarm_source_name, a.warn_time AS alarm_time, a.conf_mode, e.dict_note AS conf_mode_name, a.deal_person_id, h.user_name as deal_person_name, a.deal_time, a.std_mete_id, m.real_code, a.image_path, a.deal_info, a.deal_type, g.dict_note as deal_type_name, a.defect_model, p.dict_note as defect_model_name, n.cruise_id as preset_id, j.camera_id FROM t_warn_info a LEFT JOIN t_std_device b ON a.device_id = b.device_id and a.cunstom_id = b.custom_id LEFT JOIN t_dict_business c ON a.warn_level = c.dict_code LEFT JOIN t_dict_business d ON a.alarm_source = d.dict_code and d.col_name = 'alarm_source' LEFT JOIN t_dict_business e ON a.conf_mode = e.dict_code and e.col_name = 'conf_mode' LEFT JOIN t_std_devicemete k on a.std_mete_id = k.device_mete_id LEFT JOIN t_dict_business g on a.deal_type = g.dict_code and g.col_name = 'deal_type' LEFT JOIN sys_user h ON h.user_id = a.deal_person_id LEFT JOIN t_std_device_attr m on m.device_id = a.device_id LEFT JOIN t_cruise_point_instance n on n.instance_id = a.instance_id LEFT JOIN t_camera_preset j on j.preset_id = n.cruise_id LEFT JOIN t_dict_business p ON a.defect_model = p.dict_code and p.col_name = 'defect_model' WHERE 1 = 1 ) UNION ALL (SELECT a.defect_id, a.device_id, b.device_name, k.mete_name, b.custom_name, a.defect_content, a.defect_level AS alarm_level, c.dict_note AS alarm_level_name, a.alarm_source, d.dict_note AS alarm_source_name, a.defect_time AS alarm_time, a.conf_mode, e.dict_note AS conf_mode_name, a.deal_person_id, h.user_name as deal_person_name, a.deal_time, a.std_mete_id, m.real_code, a.image_path, a.deal_info, a.deal_type, g.dict_note as deal_type_name, a.defect_type as defect_model, p.dict_note as defect_model_name, n.cruise_id as preset_id, j.camera_id FROM t_defect_info a LEFT JOIN t_std_device b ON a.device_id = b.device_id and a.cunstom_id = b.custom_id LEFT JOIN t_dict_business c ON a.defect_level = c.dict_code and c.col_name = 'alarm_level' LEFT JOIN t_dict_business d ON a.alarm_source = d.dict_code and d.col_name = 'alarm_source' LEFT JOIN t_dict_business e ON a.conf_mode = e.dict_code and e.col_name = 'conf_mode' LEFT JOIN t_std_devicemete k on a.std_mete_id = k.device_mete_id LEFT JOIN t_dict_business g on a.deal_type = g.dict_code LEFT JOIN sys_user h ON h.user_id = a.deal_person_id LEFT JOIN t_std_device_attr m on m.device_id = a.device_id LEFT JOIN t_cruise_point_instance n on n.instance_id = a.instance_id LEFT JOIN t_camera_preset j on j.preset_id = n.cruise_id LEFT JOIN t_dict_business p ON a.defect_type = p.dict_code and p.col_name = 'defect_model' WHERE 1 = 1) ) big_table WHERE 1 = 1 and alarm_level = #{warnLevel, jdbcType=INTEGER} and conf_mode = #{confMode, jdbcType=INTEGER} and device_name like concat("%",#{deviceName, jdbcType=VARCHAR},"%") and mete_name like concat("%",#{meteName, jdbcType=VARCHAR},"%")
and alarm_time BETWEEN #{startTime, jdbcType=TIMESTAMP} AND #{endTime, jdbcType=TIMESTAMP}
and defect_model = #{defectType,jdbcType=INTEGER} ORDER BY alarm_time DESC

SELECT * FROM

where 1 = 1
 and warn_id = #{warnId, jdbcType=BIGINT}
